mapper.select:
SELECT DISTINCT t.* FROM tasks t
LEFT JOIN task_assignees ta ON t.id = ta.task_id
WHERE t.is_deleted = false
  AND (
      t.task_type = 'EVENT'
      OR (t.task_type IN ('WBS_TASK', 'MILESTONE')
          AND (t.creator_id = #{userId} OR ta.user_id = #{userId}))
  )

  AND t.start_date <= #{to}


  AND t.end_date >= #{from}

  AND (
      t.creator_id = #{userId}     
      OR ta.user_id = #{userId}   

      OR (t.visibility = 'PUBLIC'
          AND t.creator_id IN (
              SELECT id FROM users WHERE department_id IN

                  #{id}

          )
      )

  )

  AND (t.title LIKE CONCAT('%', #{keyword}, '%')
    OR t.description LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY t.start_date
LIMIT 500

SELECT * FROM tasks
WHERE creator_id = #{userId}
  AND task_type = 'TODO'
  AND is_deleted = false

    AND status = #{status}


    AND project_id = #{projectId}


    AND title LIKE CONCAT('%', #{keyword}, '%')

ORDER BY created_at DESC

SELECT DISTINCT t.* FROM tasks t
JOIN task_assignees ta ON ta.task_id = t.id
WHERE ta.user_id = #{userId}
  AND t.task_type IN ('WBS_TASK', 'MILESTONE')
  AND t.is_deleted = false

    AND t.status = #{status}


    AND t.project_id = #{projectId}


    AND t.title LIKE CONCAT('%', #{keyword}, '%')

ORDER BY t.end_date IS NULL, t.end_date, t.created_at DESC
